files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.calculator {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 8px 8px 0 #0f0f1f;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 1rem;
  color: var(--muted);
  letter-spacing: 1px;
}

input, select {
  width: 100%;
  padding: 12px;
  font-size: 1.1rem;
  font-family: inherit;
  background: #0f0f1f;
  color: var(--text);
  border: 3px solid var(--accent);
  border-radius: 0;
  outline: none;
}

input:focus, select:focus {
  border-color: #fff;
  box-shadow: 0 0 0 2px var(--accent);
}

button {
  width: 100%;
  padding: 14px;
  font-size: 1.2rem;
  font-family: inherit;
  font-weight: bold;
  letter-spacing: 2px;
  text-transform: uppercase;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.05s, background 0.1s;
  margin-bottom: 20px;
}

button:hover {
  background: #ff5c7a;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.result-box {
  background: #0f0f1f;
  border: 3px solid var(--accent);
  padding: 16px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.2rem;
}

.result-label {
  color: var(--muted);
  white-space: nowrap;
}

#result {
  font-weight: bold;
  font-size: 1.4rem;
  word-break: break-all;
}

@media (max-width: 400px) {
  .calculator {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateBtn = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const leftRaw = leftInput.value.trim();
  const rightRaw = rightInput.value.trim();

  if (leftRaw === '' || rightRaw === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const left = Number(leftRaw);
  const right = Number(rightRaw);

  if (!isFinite(left) || !isFinite(right)) {
    resultOutput.textContent = 'Error';
    return;
  }

  const op = operationSelect.value;
  let result;

  switch (op) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      result = left / right;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  if (!isFinite(result)) {
    resultOutput.textContent = 'Error';
    return;
  }

  resultOutput.textContent = String(result);
}

calculateBtn.addEventListener('click', calculate);

[leftInput, rightInput, operationSelect].forEach(el => {
  el.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      calculate();
    }
  });
});
